    marks=[(g[i][j],i,j) for i in range(H) for j in range(W) if g[i][j] not in (0,5)]
    out=[list(r) for r in g]
    hR=(r1-r0-1)//2; hC=(c1-c0-1)//2
    def blk(vr,hc):
        rr0 = r0+1 if vr==-1 else r1-hR
        cc0 = c0+1 if hc==-1 else c1-hC
        return (rr0,cc0)
    for v,i,j in marks:
        vr=-1 if i<r0 else +1
        hc=-1 if j<c0 else +1
        for vr_,hc_ in [(vr,hc),(-vr,-hc)]:
            rr0,cc0=blk(vr_,hc_)
            for ii in range(rr0,min(rr0+hR,r1-1)+1):
                pass
            for ii in range(rr0,rr0+hR):
                if rr0+hR>r1-1: break
                for jj in range(cc0,cc0+hC):
                    if cc0+hC>c1-1: break
                    out[ii][jj]=v
